mapper.select:
select

from t_biam_operation_log ol


        AND ol.user_id IN

            #{item}



        AND ol.phone = #{inputDto.phone}


        AND LOWER(ol.real_name) LIKE LOWER(CONCAT('%', #{inputDto.realName}, '%'))


        AND ol.module = #{inputDto.module}


        AND ol.module_entity = #{inputDto.moduleEntity}


        AND ol.operate_type = #{inputDto.operateType}


        AND LOWER(ol.operate_name) LIKE LOWER(CONCAT('%', #{inputDto.operateName}, '%'))


        AND ol.operate_source = #{inputDto.operateSource}


        AND ol.module_entity_id = #{inputDto.moduleEntityId}


        AND ol.http_status = #{inputDto.httpStatus}


        AND LOWER(ol.request_path) LIKE LOWER(CONCAT('%', #{inputDto.requestPath}, '%'))


        AND ol.action_status = #{inputDto.actionStatus}


        AND ol.client_ip = #{inputDto.clientIp}


        AND ol.trace_id = #{inputDto.traceId}


        AND ol.create_time >= #{inputDto.createStartTime}


        AND ol.create_time <= #{inputDto.createEndTime}


ORDER BY ol.create_time DESC
